`timescale 1ns/1ps
module l5_prefill_count_controller(
 input logic clk_i,rst_ni,start_i,command_ready_i,engine_done_i,input logic[8:0]sequence_length_i,
 output logic command_valid_o,measured_latency_valid_o,score_matrix_o,done_o,config_error_o,
 output logic[8:0]sequence_length_o,output logic[4:0]operation_o,output logic[2:0]engine_o,
 output logic[31:0]work_items_o,matrix_steps_o,commands_issued_o,matrix_steps_total_o,rope_pairs_total_o,dot_operations_total_o,online_updates_total_o,reciprocals_total_o,normalization_chunks_total_o,silu_scalars_total_o,product_chunks_total_o,score_matrix_commands_o);
 typedef enum logic[1:0]{IDLE,ISSUE,WAIT,DONE}st_e;st_e st;logic[4:0]idx;logic is384;
 function automatic[4:0]op(input[4:0]i);case(i)0,17:op=0;1:op=1;2:op=2;3:op=3;4:op=4;5:op=5;6:op=6;7:op=7;8:op=8;9:op=9;10:op=10;11:op=11;12:op=12;13:op=13;14:op=14;15:op=15;16:op=16;18:op=17;19:op=18;20:op=19;21:op=20;22:op=21;23:op=22;default:op=31;endcase endfunction
 function automatic[2:0]eng(input[4:0]i);case(i)1,2,3,15,18,19,22:eng=0;0,17:eng=1;4,5,6:eng=2;7,8,9,10:eng=3;11,12,13,14:eng=4;default:eng=5;endcase endfunction
 function automatic[31:0]work(input[4:0]i,input logic q384);if(q384)case(i)0,17:work=36864;1:work=1769472;2,3:work=294912;4:work=36864;5,6:work=6144;7:work=294912;8:work=49152;9,10:work=36864;11,12:work=887040;13:work=4608;14,16,23:work=36864;15:work=1769472;18,19,22:work=10321920;20:work=3440640;21:work=215040;default:work=0;endcase else case(i)0,17:work=12288;1:work=589824;2,3:work=98304;4:work=12288;5,6:work=2048;7:work=98304;8:work=16384;9,10:work=12288;11,12:work=99072;13:work=1536;14,16,23:work=12288;15:work=589824;18,19,22:work=3440640;20:work=1146880;21:work=71680;default:work=0;endcase endfunction
 function automatic[31:0]steps(input[4:0]i,input logic q384);if(q384)case(i)1,15:steps=1769472;2,3:steps=294912;18,19,22:steps=10321920;default:steps=0;endcase else case(i)1,15:steps=589824;2,3:steps=98304;18,19,22:steps=3440640;default:steps=0;endcase endfunction
 assign command_valid_o=st==ISSUE;assign operation_o=op(idx);assign engine_o=eng(idx);assign work_items_o=work(idx,is384);assign matrix_steps_o=steps(idx,is384);assign measured_latency_valid_o=0;assign score_matrix_o=0;assign done_o=st==DONE;assign sequence_length_o=is384?9'd384:9'd128;
 always_ff@(posedge clk_i or negedge rst_ni)begin if(!rst_ni)begin st<=IDLE;idx<=0;is384<=0;config_error_o<=0;commands_issued_o<=0;matrix_steps_total_o<=0;rope_pairs_total_o<=0;dot_operations_total_o<=0;online_updates_total_o<=0;reciprocals_total_o<=0;normalization_chunks_total_o<=0;silu_scalars_total_o<=0;product_chunks_total_o<=0;score_matrix_commands_o<=0;end else case(st)
  IDLE:if(start_i)begin idx<=0;is384<=sequence_length_i==384;config_error_o<=sequence_length_i!=128&&sequence_length_i!=384;commands_issued_o<=0;matrix_steps_total_o<=0;rope_pairs_total_o<=0;dot_operations_total_o<=0;online_updates_total_o<=0;reciprocals_total_o<=0;normalization_chunks_total_o<=0;silu_scalars_total_o<=0;product_chunks_total_o<=0;score_matrix_commands_o<=0;st<=sequence_length_i==128||sequence_length_i==384?ISSUE:DONE;end
  ISSUE:if(command_ready_i)begin commands_issued_o<=commands_issued_o+1;matrix_steps_total_o<=matrix_steps_total_o+matrix_steps_o;if(idx==7||idx==8)rope_pairs_total_o<=rope_pairs_total_o+work_items_o;if(idx==11)dot_operations_total_o<=dot_operations_total_o+work_items_o;if(idx==12)online_updates_total_o<=online_updates_total_o+work_items_o;if(idx==13)reciprocals_total_o<=reciprocals_total_o+work_items_o;if(idx==14)normalization_chunks_total_o<=normalization_chunks_total_o+work_items_o;if(idx==20)silu_scalars_total_o<=silu_scalars_total_o+work_items_o;if(idx==21)product_chunks_total_o<=product_chunks_total_o+work_items_o;if(score_matrix_o)score_matrix_commands_o<=score_matrix_commands_o+1;st<=WAIT;end
  WAIT:if(engine_done_i)begin if(idx==23)st<=DONE;else begin idx<=idx+1;st<=ISSUE;end end
  DONE:if(start_i)st<=IDLE;default:st<=IDLE;endcase end
endmodule
